  document.querySelector("#brief-preview").innerHTML=`<div class="brief-top"><div><p class="eyebrow">Monthly creator brief</p><h2>${esc(product)}</h2><p class="muted">${esc(monthPlan?.name||"")} · ${esc(owner?.name||"")} · ${esc(pillar?.name||"")}</p></div><button class="copy-button" id="copy-brief">Copy brief</button></div><div id="brief-copy"><p>Hi lovely!</p><p>For your <b>CoBa’s Daughter body-care video</b>, please follow this direction:</p><p><b>Internal production product:</b> ${esc(product)}. Do not say an unconfirmed set or bundle name on camera.</p><p><b>Product page:</b> <a href="${esc(chosen.url)}" target="_blank">Open official product ↗</a></p><p><b>Main reference:</b> <a href="${esc(mainRef)}" target="_blank">Open reference ↗</a></p>${visualRef&&visualRef!==mainRef?`<p><b>Mandatory visual reference:</b> <a href="${esc(visualRef)}" target="_blank">Open visual reference ↗</a></p>`:""}<h3>Monthly intelligence</h3><div class="viral-plan"><p><b>Month job:</b> ${esc(monthPlan?.job||"Evergreen")}</p><p><b>Pillar:</b> ${esc(pillar?.name||angle)} · ${potential.planned_posts||0} total pieces</p><p><b>Selected product allocation:</b> ${productPieces} pieces inside this pillar.</p><p><b>Selected angle allocation:</b> ${anglePieces} pieces inside this pillar.</p><p><b>Viral-potential index:</b> ${potential.score||"—"}/100. Prioritization only; not a performance forecast.</p><p><b>Owner:</b> ${esc(owner?.name||"Creator")} · ${esc(owner?.brief_depth||"")}</p></div><h3>Strategic angle</h3><p><b>${esc(angle)}</b> — ${esc(play.engine)}</p><h3>Viral format plan</h3><div class="viral-plan"><p><b>Recommended format:</b> ${esc(play.format)}</p><p><b>First frame:</b> ${esc(play.first)}</p><p><b>Edit rhythm:</b> ${esc(play.edit)}</p><p><b>Formats observed in qualifying sources:</b> ${esc(observedFormats.join(" · ")||"Reference-led test")}</p></div><h3>Main idea</h3><p>${esc(mainIdea)}</p><h3>What is supplied</h3><ul>${chosen.contents.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h3>Content direction</h3><ul>${direction.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h3>Must include / QA gates</h3><ul class="checklist">${must.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h3>Key message</h3><p>${esc(keyMessage)}</p><h3>Month-specific hook options</h3><ul>${hooks.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h3>Current sound directions</h3><ul>${soundHtml}</ul><p class="rights-note">Snapshot: ${esc(soundData.market||"US")} · verified ${esc(soundData.verified_at||"not available")}. ${esc(soundData.rights_note)}</p><p><a href="${esc(soundData.commercial_music_library_url||"https://ads.tiktok.com/business/creativecenter/music/pc/en")}" target="_blank">Check TikTok Commercial Music Library ↗</a></p><h3>CTA</h3><p>“${esc(cta)}”</p><h3>Approval gate</h3><p>The month job, pillar, product facts, selected angle, owner limitations and truthful CTA must be visible in the actual cut. No scent-dupe claim, fake urgency or unconfirmed set name.</p><h3>References</h3><p>${refs}</p></div>`;
