document.addEventListener("click",async e=>{const n=e.target.closest("[data-view]");if(n)navigate(n.dataset.view);const g=e.target.closest("[data-go]");if(g)navigate(g.dataset.go);const m=e.target.closest("[data-month]");if(m){state.month=m.dataset.month;renderMonthly()}if(e.target.closest("#copy-brief")){await navigator.clipboard.writeText(document.querySelector("#brief-copy").innerText);e.target.textContent="Copied"}if(e.target.closest("#download-creators"))downloadCreators()});document.querySelector("#search").addEventListener("input",renderRows);document.querySelector("#angle-filter").addEventListener("change",renderRows);document.querySelector("#creator-search").addEventListener("input",renderCreators);document.querySelector("#creator-us").addEventListener("change",renderCreators);document.querySelector("#creator-followers").addEventListener("change",renderCreators);for(const id of ["#brief-month","#brief-owner","#brief-pillar"]){document.querySelector(id).addEventListener("change",()=>{syncMonthlyBuilder();if(document.querySelector("#brief-copy"))briefV3()})}document.querySelector("#brief-product").addEventListener("change",()=>{renderProduct();syncMonthlyBuilder();if(document.querySelector("#brief-copy"))briefV3()});document.querySelector("#brief-angle").addEventListener("change",()=>{renderAnglePlay();if(document.querySelector("#brief-copy"))briefV3()});document.querySelector("#brief-mode").addEventListener("change",()=>{if(document.querySelector("#brief-copy"))briefV3()});document.querySelector("#generate-brief").addEventListener("click",briefV3);
